-- Проверяет обязательность/уникальность ключей и существование родителей; нарушение блокирует дочерние шаги.
SELECT count(*) n FROM (SELECT topic,kafka_partition,kafka_offset FROM {{target:oil_stg__batch_coalesce_event_map}} GROUP BY topic,kafka_partition,kafka_offset HAVING topic IS NULL OR kafka_partition IS NULL OR kafka_offset IS NULL OR count(*)<>1 UNION ALL SELECT a.topic,a.kafka_partition,a.kafka_offset FROM {{target:oil_stg__batch_coalesce_event_map}} a LEFT JOIN {{target:oil_stg__batch_coalesce_map}} m ON m.original_batch_id=a.original_batch_id AND m.coalesced_batch_id=a.coalesced_batch_id LEFT JOIN {{target:oil_stg__event_log}} e ON e.topic=a.topic AND e.kafka_partition=a.kafka_partition AND e.kafka_offset=a.kafka_offset WHERE m.original_batch_id IS NULL OR e.kafka_offset IS NULL OR e.batch_id IS DISTINCT FROM a.coalesced_batch_id) q;
